def uniq(seq):
    out=[]; seen=set()
    for x in seq:
        x=" ".join(str(x).split())
        if len(x)<5 or x in seen: continue
        seen.add(x); out.append(x)
    return out

def product(*pools):
    return [" ".join(p) for p in itertools.product(*pools)]

